		f.set_now(1.5)
		_check("F fix plan no slot", f._status_cell == null and f._stage_pct == "")

		# G: plan mode keeps today's slot (empty slot still reserves D_W_CARD_SLOT).
		var g := _row(_card("feature", {}, false, run), "plan", 0.0)
		_check("G plan empty slot width", _cell(g).custom_minimum_size.x == UiTokens.D_W_CARD_SLOT and _cell(g).get_child_count() == 0)
		var h := _row(_card("feature", due, true, run), "plan", 0.0)
		_check("H plan due wins over late", _txt(h) == "PanelContainer")

		# I: widths of the longest strings.
		await process_frame
		var worst := 0.0
		for st in ["design", "dev", "test", "product"]:
			var lab := Label.new()
			var host := Control.new()
			host.theme = load("res://themes/menajer_theme.tres")
			root.add_child(host)
			lab.theme_type_variation = &"CaptionName"
			lab.text = tr("PRODUCT_STAGE_PCT").format({"stage": SprintUiShared.stage_name(st), "pct": Fmt.percent(99.0, 0)})
			host.add_child(lab)
			var w := lab.get_combined_minimum_size().x
